// Normalise + guard the incoming payload before it goes anywhere.
const b = $input.first().json.body || $input.first().json;

const clean = (v, max = 2000) =>
  String(v ?? '').trim().slice(0, max);

// Reject if the honeypot was filled, or required fields are missing.
if (clean(b.website)) {
  return [{ json: { spam: true, reason: 'honeypot' } }];
}

const required = ['service', 'company', 'contact_name', 'phone', 'description'];
const missing = required.filter((k) => !clean(b[k]));
if (missing.length) {
  return [{ json: { spam: true, reason: 'missing:' + missing.join(',') } }];
}

const frequency = clean(b.frequency) || 'Not specified';
const isContract = /month|recur|contract/i.test(frequency);

return [{
  json: {
    spam: false,
    frequency,
    isContract,
    priority: isContract ? 'Contract enquiry — call to discuss' : 'One-time job',
    service: clean(b.service, 120),
    company: clean(b.company, 200),
    contact_name: clean(b.contact_name, 200),
    phone: clean(b.phone, 60),
    description: clean(b.description, 4000),
    submitted_at: clean(b.submitted_at, 60) || new Date().toISOString(),
    received_at: new Date().toISOString(),
    source: clean(b.source, 200)
  }
}];

